static void expectConsole(bool b,const char* text){if(!b)throw std::runtime_error(text);}
static void waitConsole(orbit::mixing::SpriteBrowser& b){const auto end=juce::Time::getMillisecondCounterHiRes()+20000;while(b.loading&&juce::Time::getMillisecondCounterHiRes()<end){juce::Thread::sleep(5);b.poll();}expectConsole(!b.loading,"sprite worker timeout");}
